/**
 * Sound effects as timed POKEY register writes, traced from the original sound
 * board's effect tables: for each effect, every register write the sound CPU's
 * sequencer would make, in beats of about 8.13 ms. Data only; do not edit by
 * hand. Effects use chips 0 and 1; the music uses chips 2 and 3.
 */

export interface EffectStep {
  /** Beat at which the write happens. */
  t: number;
  /** Register within the chip: 0-7 AUDF/AUDC pairs, 8 AUDCTL. */
  reg: number;
  value: number;
}

export interface Effect {
  /** Which of the four chips, and which channels it occupies (0-3). */
  chip: number;
  channels: number[];
  /** Beats per second of the sound CPU's sequencer. */
  tickHz: number;
  steps: EffectStep[];
  /** Beats until the effect is silent. */
  length: number;
  loop?: boolean;
  /** Higher wins when two effects want the same channels; the original had no priorities. */
  priority: number;
}

export const BEAT_HZ = 123.0012;

